function roomBackgroundNow() {
  const h = new Date().getHours();
  const m = new Date().getMonth();
  const season = (m === 11 || m <= 1) ? "winter" : m <= 4 ? "spring" : m <= 7 ? "summer" : "autumn";
  const phase = (h >= 6 && h < 20) ? "day" : "night";
  return ROOM_BACKGROUNDS[season + "_" + phase] || ROOM_BACKGROUNDS.summer_night;
}
