    const idx = (typeof forcedIdx === 'number') ? forcedIdx : rollWheelIndex(wheel.segs, eco.pityRare || 0);
    const segW = 360 / wheel.segs.length;
    const target = 360 * 6 + (360 - (idx * segW + segW / 2));
