function emptyNpcBond(id) {
  return { id, affinity: 40, mood: 'neutral', notes: [], lastSpoke: null };
}
function emptyCouncil() {
  return {
    lastMorningDate: null,
    lastNoonDate: null,
    meetings: [],
    pending: null,
    grants: { achievements: [], titles: [], gear: [], cosmetics: [] },
    facts: [],
    chats: {},
    room: [],
    bonds: Object.fromEntries((typeof COUNCIL_NPCS !== 'undefined' ? COUNCIL_NPCS : []).map(n => [n.id, emptyNpcBond(n.id)])),
  };
}

function normalizeCouncil(c) {
  const d = emptyCouncil();
  if (!c || typeof c !== 'object') return d;
  const bonds = { ...d.bonds, ...(c.bonds || {}) };
  (typeof COUNCIL_NPCS !== 'undefined' ? COUNCIL_NPCS : []).forEach(n => {
    if (!bonds[n.id]) bonds[n.id] = emptyNpcBond(n.id);
  });
  return {
    ...d,
    ...c,
    meetings: Array.isArray(c.meetings) ? c.meetings.slice(0, 30) : [],
    grants: { ...d.grants, ...(c.grants || {}) },
    pending: c.pending || null,
    facts: Array.isArray(c.facts) ? c.facts.slice(0, 80) : [],
    chats: c.chats && typeof c.chats === 'object' ? c.chats : {},
    room: Array.isArray(c.room) ? c.room.slice(-80) : [],
    bonds,
  };
}

function councilSlotNow() {
  const h = new Date().getHours();
  if (h >= 5 && h < 12) return 'morning';
  if (h >= 12 && h < 17) return 'noon';
  return 'evening';
}

function councilDue(council) {
  const c = normalizeCouncil(council);
  const today = todayStr();
  const slot = councilSlotNow();
  if (slot === 'morning' && c.lastMorningDate !== today) return 'morning';
  if (slot === 'noon' && c.lastNoonDate !== today) return 'noon';
  return null;
}


const CONTEXT_BUDGET = {
  COUNCIL: 3600,
  CHAT: 2400,
  MENTOR: 2400,
  CONTENT_IDEAS: 1800,
  CONTENT_PLAN: 1800,
  YOUTUBE_ANALYTICS: 1600,
  GOAL_PLANNING: 2000,
  QUEST_GENERATION: 1600,
  DEFAULT: 2000,
};

const ContextManager = {
  clip(v, n) {
    const s = v == null ? '' : String(v);
    return s.length <= n ? s : s.slice(0, n - 1) + '…';
  },
  uniq(arr) {
    const seen = new Set();
    const out = [];
    (arr || []).forEach(x => {
      const k = typeof x === 'string' ? x : JSON.stringify(x);
      if (!k || seen.has(k)) return;
      seen.add(k);
      out.push(x);
    });
    return out;
  },
  takeChars(items, max, fmt) {
    const out = [];
    let used = 0;
    for (const it of items || []) {
      const s = fmt(it);
      if (!s) continue;
      if (used + s.length > max) break;
      out.push(typeof it === 'string' ? s : it);
      used += s.length + 1;
    }
    return out;
  },
  gameSlice(state) {
    const yt = normalizeYoutube(state.youtube || { channels: [] });
    return {
      hero: this.clip(state.character?.name, 24),
      lv: state.character?.level,
      title: this.clip(state.character?.title, 32),
      coins: state.coins,
      recovery: !!state.recoveryMode,
      quests: (state.quests || []).filter(q => q.status === 'active').slice(0, 4).map(q => this.clip(q.title, 42)),
      goals: (state.goals || []).slice(0, 3).map(g => this.clip(`${g.title}:${g.progress || 0}%`, 48)),
      habits: (state.habits || []).slice(0, 3).map(h => this.clip(`${h.title}#${h.streakCurrent || 0}`, 40)),
      cash: state.finance?.cashBalance,
      debts: (state.finance?.debts || []).filter(d => d.remaining > 0).length,
      yt: { n: yt.channels.length, ideas: yt.ideas.length, work: yt.contentItems.filter(i => i.status !== 'PUBLISHED').length },
    };
  },
  memorySlice(council, budget) {
    const c = normalizeCouncil(council);
    const facts = this.takeChars(c.facts || [], Math.floor(budget * 0.35), f => (f && f.text) || '');
    const meetings = this.takeChars(c.meetings || [], Math.floor(budget * 0.25), m => `${m.slot}:${m.memory || m.director || ''}`);
    const bonds = Object.values(c.bonds || {}).map(b => ({
      id: b.id,
      aff: b.affinity,
      mood: b.mood,
      notes: (b.notes || []).slice(0, 3).map(n => this.clip(n.text, 80)),
    }));
    return { facts: facts.map(f => this.clip(f.text || f, 140)), meetings: meetings.map(m => ({ d: m.slot, t: this.clip(m.memory || m.director, 120) })), bonds };
  },
  build(taskType, state, extra = {}) {
    const cap = CONTEXT_BUDGET[taskType] || CONTEXT_BUDGET.DEFAULT;
    const payload = {
      task: taskType,
      game: this.gameSlice(state),
      memory: this.memorySlice(state.council, cap),
      ...extra,
    };
    let raw = JSON.stringify(payload);
    if (raw.length <= cap) return payload;
    const slim = { task: taskType, game: payload.game, memory: { facts: payload.memory.facts.slice(0, 8), bonds: payload.memory.bonds, meetings: payload.memory.meetings.slice(0, 4) }, topic: extra.topic || extra.slot || null };
    raw = JSON.stringify(slim);
    if (raw.length <= cap) return slim;
    return { task: taskType, game: payload.game, topic: extra.topic || null };
  },
};

function councilStateBrief(state) {
  const w = latestWeight(state.body);
  const yt = normalizeYoutube(state.youtube || { channels: [] });
  const debts = (state.finance?.debts || []).filter(d => d.remaining > 0).length;
  const activeQ = (state.quests || []).filter(q => q.status === 'active').slice(0, 5).map(q => q.title);
  const goals = (state.goals || []).slice(0, 3).map(g => `${g.title} ${g.progress || 0}%`);
  const habits = (state.habits || []).slice(0, 4).map(h => `${h.title} стрик ${h.streakCurrent || 0}`);
  return {
    name: state.character?.name, level: state.character?.level, title: state.character?.title,
    coins: state.coins, energyHint: 'смотри чекин',
    height: state.body?.heightCm, weight: w, recovery: !!state.recoveryMode,
    activeQuests: activeQ, goals, habits,
    cash: state.finance?.cashBalance, openDebts: debts,
    ytChannels: yt.channels.length, ytIdeas: yt.ideas.length, ytPipeline: yt.contentItems.filter(i => i.status !== 'PUBLISHED').length,
  };
}

function parseCouncilJson(text) {
  const cleaned = String(text || '').replace(/```json|```/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('no JSON');
  return JSON.parse(cleaned.slice(start, end + 1));
}

function pickEnterOrder() {
  const withDelay = COUNCIL_NPCS.map(n => ({ n, t: 300 + Math.random() * 900 + (Math.random() < n.late ? 1400 + Math.random() * 1800 : 0) }));
  withDelay.sort((a, b) => a.t - b.t);
  return withDelay;
}

function CouncilTab({ state, energy, runCouncil, acceptCouncil, dismissCouncil, setCharacterTitle, talkToNpc, sendCouncilChat, appendCouncilRoom }) {
  const council = normalizeCouncil(state.council);
  const [view, setView] = useState('hall');
  const [topic, setTopic] = useState('');
  const [draft, setDraft] = useState('');
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState(null);
  const [joining, setJoining] = useState([]);
  const [typingWho, setTypingWho] = useState(null);
  const [meeting, setMeeting] = useState(null);
  const due = councilDue(state.council);
  const pending = council.pending;
  const npcId = view.startsWith('npc:') ? view.slice(4) : null;
  const npc = COUNCIL_NPCS.find(n => n.id === npcId);
  const dm = npc ? (council.chats[npc.id] || []) : [];
  const room = council.room || [];

  async function playLines(lines) {
    for (const line of lines || []) {
      setTypingWho(line.who);
      await new Promise(r => setTimeout(r, 650 + Math.random() * 900));
      setJoining(prev => [...prev, line]);
      if (appendCouncilRoom) appendCouncilRoom([line]);
      setTypingWho(null);
      await new Promise(r => setTimeout(r, 280));
    }
  }

  async function startRoom() {
    const theme = topic.trim() || 'Встреча штаба';
    setView('room'); setErr(null); setTypingWho(null);
    setMeeting({ title: theme, at: Date.now() });
    const divider = { id: 'meet-' + Date.now(), kind: 'meet', who: 'system', text: theme, ts: Date.now() };
    setJoining([divider]);
    if (appendCouncilRoom) appendCouncilRoom([divider]);
    setBusy(true);
    const order = pickEnterOrder();
    const aiP = sendCouncilChat(theme, null, 'open').catch(e => { setErr(e.message || String(e)); return []; });
    let acc = [];
    for (const step of order) {
      setTypingWho(step.n.id);
      await new Promise(r => setTimeout(r, Math.min(step.t, 1600)));
      const line = { id: 'join-' + step.n.id + Date.now(), who: step.n.id, text: step.n.enter[Math.floor(Math.random() * step.n.enter.length)], kind: 'join', ts: Date.now() };
      acc = [...acc, line];
      setJoining(acc);
      setTypingWho(null);
      await new Promise(r => setTimeout(r, 220));
    }
    const lines = await aiP;
    await playLines(lines);
    setTopic('');
    setBusy(false);
  }

  async function sendRoom() {
    if (!draft.trim() || busy) return;
    const text = draft.trim(); setDraft(''); setBusy(true); setErr(null);
    try {
      const lines = await sendCouncilChat(text, null, 'talk');
      await playLines(lines);
    } catch (e) { setErr(e.message || String(e)); }
    setBusy(false);
  }

  async function sendDm() {
    if (!draft.trim() || !npc || busy) return;
    const text = draft.trim(); setDraft(''); setBusy(true); setErr(null);
    try { await talkToNpc(npc.id, text); }
    catch (e) { setErr(e.message || String(e)); }
    setBusy(false);
  }

  async function reco() {
    setBusy(true); setErr(null);
    try { await runCouncil(due || 'topic', topic); }
    catch (e) { setErr(e.message || String(e)); }
    setBusy(false);
  }

  if (view === 'room') {
    const shown = [...joining.filter(j => !room.some(r => r.kind === 'join' && r.who === j.who)), ...room];
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, height: 'calc(100dvh - 148px)', minHeight: 420 }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, flexShrink: 0 }}>
          <button className="lrpg-btn" onClick={() => setView('hall')} style={{ background: 'rgba(255,255,255,0.06)', borderRadius: 999, padding: '8px 12px', color: COLORS.text, fontSize: 13 }}>← Зал</button>
          <div style={{ fontSize: 14, fontWeight: 800 }}>Совет</div>
          <button className="lrpg-btn" onClick={() => setView('hall')} style={{ background: 'rgba(255,255,255,0.06)', borderRadius: 999, padding: '8px 12px', fontSize: 12, color: COLORS.textMuted }}>Выйти</button>
        </div>
        <div style={{ display: 'flex', gap: 6, minHeight: 52, marginBottom: 4 }}>
          {COUNCIL_NPCS.filter(n => shown.some(m => m.who === n.id)).map((n, i) => (
            <div key={n.id} style={{
              width: 44, textAlign: 'center', animation: 'lrpg-npc-in .45s ease-out both', animationDelay: `${i * 40}ms`,
            }}>
              <div style={{
                width: 40, height: 40, borderRadius: '50%', margin: '0 auto',
                background: 'linear-gradient(180deg,#2a2540,#151822)',
                border: typingWho === n.id ? '1px solid #00E5FF' : '1px solid rgba(108,99,255,.45)',
                display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18,
                animation: typingWho === n.id ? 'lrpg-pulse 1.1s ease-out infinite' : 'none',
              }}>{n.emoji}</div>
              <div style={{ fontSize: 9, color: typingWho === n.id ? '#00E5FF' : COLORS.textMuted, marginTop: 2 }}>{n.name}</div>
            </div>
          ))}
        </div>
        <div style={{ flex: 1, overflowY: 'auto', WebkitOverflowScrolling: 'touch', display: 'flex', flexDirection: 'column', gap: 8, paddingBottom: 8 }}>
          {shown.map(m => {
            if (m.kind === 'meet') {
              const tm = new Date(m.ts || Date.now()).toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });
              return (
                <div key={m.id || m.ts} style={{ alignSelf: 'center', textAlign: 'center', margin: '10px 0', animation: 'lrpg-div .35s ease-out' }}>
                  <div style={{ fontSize: 10, letterSpacing: 1, color: COLORS.textMuted, textTransform: 'uppercase' }}>встреча</div>
                  <div style={{ fontSize: 13, fontWeight: 800, color: '#E8EEF8' }}>{m.text}</div>
                  <div style={{ fontSize: 11, color: '#00E5FF', marginTop: 2 }}>{tm}</div>
                </div>
              );
            }
            const n = COUNCIL_NPCS.find(x => x.id === m.who);
            const mine = m.who === 'you';
            return (
              <div key={m.id || m.ts} style={{
                alignSelf: mine ? 'flex-end' : 'flex-start', maxWidth: '88%',
                animation: 'lrpg-pop .32s cubic-bezier(.2,1.4,.4,1)',
              }}>
                {m.kind === 'join' && (
                  <div style={{ fontSize: 10, color: COLORS.teal, marginBottom: 2 }}>вошёл в комнату</div>
                )}
                <div style={{ fontSize: 10, color: COLORS.textMuted, marginBottom: 3 }}>{mine ? 'Ты' : `${n?.emoji || ''} ${n?.name || m.who}`}</div>
                <div style={{
                  fontSize: 13, padding: '8px 10px', borderRadius: mine ? '14px 14px 4px 14px' : '14px 14px 14px 4px',
                  background: mine ? 'linear-gradient(180deg,#5b54d6,#6C63FF)' : 'rgba(255,255,255,0.07)',
                  boxShadow: mine ? '0 6px 16px rgba(108,99,255,.25)' : 'none',
                }}>{m.text}</div>
              </div>
            );
          })}
          {typingWho && (
            <div style={{ alignSelf: 'flex-start', animation: 'lrpg-pop .25s ease-out' }}>
              <div style={{ fontSize: 10, color: COLORS.textMuted, marginBottom: 3 }}>{(COUNCIL_NPCS.find(n => n.id === typingWho) || {}).name} печатает</div>
              <div style={{ display: 'flex', gap: 4, padding: '8px 12px', borderRadius: '14px 14px 14px 4px', background: 'rgba(255,255,255,0.07)' }}>
                {[0,1,2].map(i => <span key={i} style={{ width: 6, height: 6, borderRadius: '50%', background: '#00E5FF', animation: `lrpg-dot 1s ${i*0.15}s infinite` }} />)}
              </div>
            </div>
          )}
        </div>
        {err && <div style={{ fontSize: 11, color: COLORS.crimson }}>{err}</div>}
        <div style={{ display: 'flex', gap: 6, flexShrink: 0 }}>
          <input className="lrpg-input" placeholder="Скажи совету что угодно" value={draft} onChange={e => setDraft(e.target.value)} />
          <button className="lrpg-btn lrpg-cta" disabled={busy} onClick={sendRoom}>➤</button>
        </div>
      </div>
    );
  }

  if (npc) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, height: 'calc(100dvh - 148px)', minHeight: 420 }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexShrink: 0 }}>
          <button className="lrpg-btn" onClick={() => setView('hall')} style={{ background: 'rgba(255,255,255,0.06)', borderRadius: 999, padding: '8px 12px', fontSize: 13 }}>← Зал</button>
          <button className="lrpg-btn" onClick={() => setView('hall')} style={{ background: 'rgba(255,255,255,0.06)', borderRadius: 999, padding: '8px 12px', fontSize: 12, color: COLORS.textMuted }}>Выйти</button>
        </div>
        <div style={{ fontSize: 15, fontWeight: 800, flexShrink: 0 }}>{npc.emoji} {npc.name}</div>
        <div style={{ fontSize: 11, color: COLORS.textMuted, flexShrink: 0 }}>{npc.role} · связь {(council.bonds[npc.id] || {}).affinity ?? 40}</div>
        <div style={{ flex: 1, overflowY: 'auto', WebkitOverflowScrolling: 'touch', display: 'flex', flexDirection: 'column', gap: 8 }}>
        {dm.length === 0 && <div style={{ fontSize: 12, color: COLORS.textMuted }}>{npc.greet[0]}</div>}
        {dm.map(m => (
          <div key={m.ts} style={{ alignSelf: m.who === 'you' ? 'flex-end' : 'flex-start', maxWidth: '88%' }}>
            <div style={{ fontSize: 13, padding: '8px 10px', borderRadius: 12, background: m.who === 'you' ? 'rgba(108,99,255,0.25)' : 'rgba(255,255,255,0.06)' }}>{m.text}</div>
          </div>
        ))}
        {busy && <div style={{ fontSize: 11, color: COLORS.textMuted }}>{npc.name} печатает…</div>}
        </div>
        {err && <div style={{ fontSize: 11, color: COLORS.crimson }}>{err}</div>}
        <div style={{ display: 'flex', gap: 6, flexShrink: 0 }}>
          <input className="lrpg-input" placeholder={'Написать ' + npc.name} value={draft} onChange={e => setDraft(e.target.value)} />
          <button className="lrpg-btn lrpg-cta" disabled={busy} onClick={sendDm}>➤</button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      <ScreenHeader title="Штаб Кайлена" icon={Users} />
      <div style={{ fontSize: 11, color: COLORS.textMuted }}>Поговори с кем-то лично или собери всех в чат. Рекомендации штаба — отдельно.</div>
      {COUNCIL_NPCS.map(n => {
        const b = council.bonds[n.id] || emptyNpcBond(n.id);
        return (
          <button key={n.id} className="lrpg-btn" onClick={() => { setView('npc:' + n.id); setDraft(''); setErr(null); }}
            style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 12px', borderRadius: 14, background: 'rgba(255,255,255,0.04)', textAlign: 'left' }}>
            <span><span style={{ fontSize: 16 }}>{n.emoji}</span> <b>{n.name}</b> · {n.role}</span>
            <span style={{ fontSize: 10, color: COLORS.textMuted }}>{b.affinity}</span>
          </button>
        );
      })}
      <input className="lrpg-input" placeholder="Тема, если есть (необязательно)" value={topic} onChange={e => setTopic(e.target.value)} />
      <button className="lrpg-btn lrpg-cta" disabled={busy} onClick={startRoom}>{busy ? 'Собираются…' : 'Собрать совет'}</button>
      <button className="lrpg-btn" disabled={busy} onClick={reco} style={{ background: COLORS.bgCardAlt, borderRadius: 999, padding: '8px 12px' }}>Дать рекомендации</button>
      {err && <div style={{ fontSize: 11, color: COLORS.crimson }}>{err}</div>}
      {pending && (
        <HudCard style={{ padding: 12, border: `1px solid ${COLORS.gold}55` }}>
          <div style={{ fontSize: 12, fontWeight: 800, color: COLORS.gold }}>Рекомендации штаба</div>
          <div style={{ fontSize: 12, marginTop: 6, whiteSpace: 'pre-wrap' }}>{pending.director}</div>
          {(pending.actions || []).map((a, i) => <div key={i} style={{ fontSize: 11, color: COLORS.textMuted }}>• {a.type}: {a.label || a.title}</div>)}
          <div style={{ display: 'flex', gap: 8, marginTop: 10 }}>
            <button className="lrpg-btn lrpg-cta" onClick={acceptCouncil}>Принять</button>
            <button className="lrpg-btn" onClick={dismissCouncil} style={{ background: COLORS.bgCardAlt, borderRadius: 999, padding: '8px 12px' }}>Отклонить</button>
          </div>
        </HudCard>
      )}
    </div>
  );
}

const COUNCIL_SYSTEM = `Ты секретарь штаба Life RPG. Директор — Мастер Кайлен. Отвечай ТОЛЬКО JSON без markdown.
Формат:
{"director":"итог Кайлена 1-3 предложения","lines":[{"id":"brum","text":"..."}],"actions":[{"type":"achievement|title|gear|cosmetic|quest","label":"коротко","desc":"","rarity":"Common|Rare","slot":"clothes|weapon|accessory"}],"memory":"1 фраза, что штаб должен помнить"}
Правила:
- lines: выступите Кайлен (id kaylen) и 3-5 других NPC из списка. Каждый говорит СВОИМ характером и ТОЛЬКО про свою область. Не повторяйте друг друга.
- Не выдумывайте метрики, которых нет во входе.
- actions необязательны и редки. Максимум 3. Ачивка/титул/шмот — только если игрок реально сделал что-то достойное в данных, не за «потенциал».
- quest в actions — один маленький квест на сегодня, если дыра очевидна.
- Помните прошлые заседания из блока ПАМЯТЬ: ссылайтесь на вчера/неделю, если это уместно.
- Язык русский, коротко.`;


